import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

argmin_source = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void argmin_dim1_kernel(const float* x, int* out, int N, int M, int K) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total = N * K;
    if (idx < total) {
        int n = idx / K;
        int k = idx % K;
        float min_val = x[n*M*K + 0*K + k];
        int min_idx = 0;
        for (int m = 1; m < M; m++) {
            float val = x[n*M*K + m*K + k];
            if (val < min_val) {
                min_val = val;
                min_idx = m;
            }
        }
        out[n*K + k] = min_idx;
    }
}

torch::Tensor argmin_cuda(torch::Tensor x, int dim) {
    // This implementation handles dim=1 for a 3D tensor [N, M, K].
    // For other cases, you may want to fallback to PyTorch's built-in or extend the kernel.
    TORCH_CHECK(x.dim() == 3, "Expected a 3D tensor for this custom kernel.");

    int64_t N = x.size(0);
    int64_t M = x.size(1);
    int64_t K = x.size(2);

    auto opts = torch::TensorOptions().dtype(torch::kInt32).device(x.device());
    auto out = torch::empty({N, K}, opts);

    int total = N * K;
    int blockSize = 256;
    int gridSize = (total + blockSize - 1) / blockSize;

    argmin_dim1_kernel<<<gridSize, blockSize>>>(x.data_ptr<float>(), out.data_ptr<int>(), N, M, K);
    return out;
}
""".strip()

argmin_cpp_source = "torch::Tensor argmin_cuda(torch::Tensor x, int dim);"

argmin_module = load_inline(
    name="argmin_module",
    cpp_sources=argmin_cpp_source,
    cuda_sources=argmin_source,
    functions=["argmin_cuda"],
    verbose=False,
)

class ModelNew(nn.Module):
    """
    Optimized model that finds the index of the minimum value along a specified dimension
    using a custom CUDA kernel for dim=1. Falls back to torch.argmin otherwise.
    """
    def __init__(self, dim: int):
        super(ModelNew, self).__init__()
        self.dim = dim

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        if self.dim == 1 and x.dim() == 3:
            return argmin_module.argmin_cuda(x, self.dim)
        else:
            return torch.argmin(x, dim=self.dim)

